import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma, Integer delta, Integer epsilon, Integer zeta,
            Grade grade, Integer weight, Kind kind, Integer verge, Integer thrust, Integer drift, Integer momentum, Integer force, Integer sway, Integer torque, Integer pivot, Integer blend, Integer flux, Integer crest, Integer swing, Integer haul, String phase, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective,
            Integer clout, Integer influence, List<String> regions, Integer reach, Integer gust,
            List<PatronView> allies, int allyCount, Integer synergy, Integer combined, Integer score, int noteSum, Integer quality, Integer adjusted, String band, Integer scaled, Integer thrum, Integer spool, String drag, Integer lift, Integer norm, boolean outlier, State state) {
        static PersonView of(Person p, Map<Long, Integer> ranks, Integer medianScaled, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(), p.getDelta(), p.getEpsilon(), p.getZeta(),
                    p.getGrade(), p.getWeight(), p.getKind(), p.getVerge(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getForce(), p.getSway(), p.getTorque(), p.getPivot(), p.getBlend(), p.getFlux(), p.getCrest(), p.getSwing(), p.getHaul(), p.getPhase(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective(), p.getClout(),
                    p.getInfluence(), p.getRegions(), p.getReach(), p.getGust(),
                    p.getAllies().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getAllies().size(), p.getSynergy(), p.getCombined(), p.getScore(), p.getNoteSum(), p.getQuality(), p.getAdjusted(), p.getBand(), p.getScaled(), p.getThrum(), p.getSpool(), p.getDrag(), p.getLift(),
                    PersonController.norm(p.getScaled(), medianScaled),
                    PersonController.outlier(PersonController.norm(p.getScaled(), medianScaled)), p.getState());
        }
    }

 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. "Clout" is the average of the
 * patrons' effective, rounded down (zero without patrons). "Influence" is effective plus clout.
 * A person may belong to any number of "regions": short codes typed in, like N1 or S2. A region's
 * "multiplier" comes from its first letter: N is 2, S is 3, any other is 1. "Reach" is the sum, over the
 * person's regions, of momentum times that region's multiplier. "Gust" is reach plus torque. A person may follow any number of other people on
 * the list, without being followed back; their "allies" are the people they follow. "Synergy" is the
 * allies' thrust added together (zero without allies). "Combined" is influence plus synergy.
    /** Spool is thrum minus blend; absent while either is absent. */
    public Integer getSpool() {
        Integer thrum = getThrum();
        Integer blend = getBlend();
        return thrum == null || blend == null ? null : thrum - blend;
    }

    /** Gust is reach plus torque; absent while either is absent. */
    public Integer getGust() {
        Integer reach = getReach();
        Integer torque = getTorque();
        return reach == null || torque == null ? null : reach + torque;
    }
}
  active: boolean;
  state: State;
  effective: number | null;
  clout: number | null;
  influence: number | null;
  regions: string[];
  reach: number | null;
  gust: number | null;
  allies: Ally[];
  allyCount: number;
  synergy: number | null;
  combined: number | null;
  score: number | null;
  noteSum: number;
  quality: number | null;
  adjusted: number | null;
// sorted ascending.
// Their reach is the sum, over their regions, of momentum times the region's multiplier, from its first
// letter: N 2, S 3, any other 1 ("n/a" while momentum is missing or they have no region).
// Their gust is their reach plus their torque ("n/a" while either is "n/a").
// The sheet's region counts show, for each region its people have, how many of them are in it
// (a person counts once in every region they belong to), ordered by region code.
// Each person may follow any number of other people, chosen on the row; following is one-directional,
          <th scope="col">Swing</th>
          <th scope="col">Haul</th>
          <th scope="col">Phase</th>
          <th scope="col">Reach</th>
