            <td data-testid="person-patrons">{{ patronNames(p) }}</td>
            <td data-testid="person-allies">{{ allyNames(p) }}</td>
            <td data-testid="person-ally-count">{{ p.allyCount }}</td>
            <td data-testid="concept-synergy">{{ p.synergy ?? 'n/a' }}</td>

